style.css:
@-moz-document domain("x.com") {
/* Основний фон сторінки */
    body {
        background-color: #16202a !important;
    }
    
    /* Фон основного контейнера */
    [data-testid="primaryColumn"],
    main {
        background-color: #16202a !important;
    }
    
    /* Фон бічних панелей */
    [data-testid="sidebarColumn"] {
        background-color: #16202a !important;
    }
    
    /* Фон модальних вікон */
    [role="dialog"] {
        background-color: #16202a !important;
    }
    
    /* Додаткові елементи */
    div[style*="background-color"] {
        background-color: #16202a !important;
    }
}
